EXPECTED_HOST_BLOB = "d53e14992608fbd3a74702fb18d423e27615b040"


def git_blob_sha(path: Path) -> str:
    data = path.read_bytes()
    return hashlib.sha1(f"blob {len(data)}\0".encode() + data).hexdigest()


host_path = ROOT / HOST
actual_host_blob = git_blob_sha(host_path)
if actual_host_blob != EXPECTED_HOST_BLOB:
    raise SystemExit(f"HostScreen blob mismatch: {actual_host_blob} != {EXPECTED_HOST_BLOB}")
if (ROOT / CONTROLS).exists():
    raise SystemExit(f"new target already exists: {CONTROLS}")

